codeExamples.code:
// Traditional I/O
var result = db.query("select x from table Y");
doSomeThingWith(result);      // wait for result!
doSomeThingWithOutResult();   // execution is blocked!

// Non-traditional, non-blocking I/O
db.query("select x from table Y", function(result) {
    doSomethingWith(result);  // wait for result!
});
doSomeThingWithOutResult();   // executes without any delay

var http = require('http');

http.createServer(function (req, res) {
  res.writeHead(200, {'Content-Type': 'text/html'});
  res.end('Hello World!');
}).listen(8080);

